  CONSTRAINT `dwh_fact_penjualan_ibfk_2` FOREIGN KEY (`id_dim_produk`) REFERENCES `dwh_dim_produk` (`id_dim_produk`) ON DELETE CASCADE,
  CONSTRAINT `dwh_fact_penjualan_ibfk_3` FOREIGN KEY (`id_dim_cabang`) REFERENCES `dwh_dim_cabang` (`id_dim_cabang`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
